<?php
declare(strict_types=1);
namespace Tests\Integration;
use PHPUnit\Framework\TestCase;
require_once dirname(__DIR__,2).'/includes/accounting_club_export.php';
final class AccountingClubExportTest extends TestCase
{
 private function snapshot():array{return['period_from'=>'2026-10-01','period_to'=>'2026-10-31','status'=>'NEÚPLNÝ','limitations'=>['TEST účetní metodika čeká na potvrzení'],'exceptions'=>[],'club_expenses'=>[['id'=>1,'root_id'=>1,'state'=>'approved','approved_at'=>'2026-09-15 12:00:00','accepted_minor'=>100000,'creditor_label'=>'TEST trenér','currency'=>'CZK']],'club_advances'=>[['id'=>7,'recipient_label'=>'TEST vedoucí','currency'=>'CZK']],'club_consumptions'=>[['claim_root_id'=>1,'advance_id'=>7,'amount_minor'=>20000,'effective_on'=>'2026-10-12']],'club_transfers'=>[],'allocations'=>[['case_type'=>'expense_claim','case_id'=>1,'amount_minor'=>30000,'effective_on'=>'2026-09-20'],['case_type'=>'expense_claim','case_id'=>1,'amount_minor'=>40000,'effective_on'=>'2026-10-20'],['case_type'=>'expense_claim','case_id'=>1,'amount_minor'=>10000,'effective_on'=>'2026-11-01'],['case_type'=>'expense_advance_out','case_id'=>7,'amount_minor'=>50000,'effective_on'=>'2026-09-30'],['case_type'=>'expense_advance_in','case_id'=>7,'amount_minor'=>10000,'effective_on'=>'2026-10-22']],'club_reward_claims'=>[['id'=>9,'kind'=>'coach','subject_id'=>13,'currency'=>'CZK']],'club_reward_versions'=>[['id'=>3,'claim_id'=>9,'amount_minor'=>90000],['id'=>5,'claim_id'=>9,'amount_minor'=>120000]],'club_reward_decisions'=>[['version_id'=>3,'outcome'=>'approved','decided_on'=>'2026-09-30'],['version_id'=>5,'outcome'=>'approved','decided_on'=>'2026-10-15']],'club_reward_payouts'=>[['claim_id'=>9,'amount_minor'=>20000,'paid_on'=>'2026-09-30'],['claim_id'=>9,'amount_minor'=>30000,'paid_on'=>'2026-10-20'],['claim_id'=>9,'amount_minor'=>70000,'paid_on'=>'2026-11-01']]];}
 public function testDatedOpeningClosingNoFuturePaymentAndNoDuplicateRewardVersions():void{$rows=\accountingClubBalanceRows($this->snapshot());self::assertCount(3,$rows);self::assertSame([700,-600,100],array_slice($rows[0],3,3));self::assertSame([500,-300,200],array_slice($rows[1],3,3));self::assertSame([700,0,700],array_slice($rows[2],3,3));}
 public function testAdvanceTransferAndReversedConsumptionAreNotCash():void{$s=$this->snapshot();$s['club_consumptions'][]=['claim_root_id'=>1,'advance_id'=>7,'amount_minor'=>-10000,'effective_on'=>'2026-10-23'];$s['club_transfers'][]=['from_advance_id'=>7,'to_advance_id'=>8,'amount_minor'=>10000,'effective_on'=>'2026-10-24'];$r=\accountingClubBalanceRows($s);self::assertSame(200,$r[0][5]);self::assertSame(200,$r[1][5]);}
 public function testPdfContainsRealPagesAndNeverLoadsRemoteUrls():void{$bytes=\accountingClubStatementPdf($this->snapshot());self::assertStringStartsWith('%PDF-',$bytes);self::assertStringContainsString('/Type /Page',$bytes);self::assertGreaterThan(10000,strlen($bytes));}
 public function testUnknownHistoricReceivableIsNotInventedAsZero():void{$s=$this->snapshot();$s['club_receivables']=[['id'=>'order:15','case_type'=>'order','case_id'=>15,'reference'=>'0000015','amount_minor'=>100000,'currency'=>'CZK','historical_status'=>'NEOVĚŘENO']];$r=\accountingClubBalanceRows($s);self::assertSame([null,null,null],array_slice($r[3],3,3));}
 public function testCorrectedExpenseUsesVerifiedOpeningAndActualReturn():void{$s=$this->snapshot();$s['club_expenses'][0]['approved_at']='2026-10-23 12:00:00';$s['club_expenses'][0]['accepted_minor']=50000;$s['club_expenses'][0]['opening_remaining_minor']=70000;$s['club_expenses'][0]['remaining_minor']=-20000;$rows=\accountingClubBalanceRows($s);self::assertSame('Pohledávka vratky výdaje',$rows[0][0]);self::assertSame([700,-900,-200],array_slice($rows[0],3,3));unset($s['club_expenses'][0]['remaining_minor'],$s['club_expenses'][0]['opening_remaining_minor']);$s['allocations'][]=['case_type'=>'expense_claim_return','case_id'=>1,'amount_minor'=>40000,'effective_on'=>'2026-10-25'];$rows=\accountingClubBalanceRows($s);self::assertSame(0,$rows[0][5]);}
}
